entries[456958] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nBrute Force Idol\nWhen Brann calls for it, jumping on him will cause him to hurl players into their enemies, knocking and dealing significant Physical damage split between them. This effect has a chance to occur up to 2 times in a row.\n\nYou already have this curio in your collection." }
entries[456959] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nIdol of the Earthmother\nBrann's spells and abilities have a chance to awaken the idol, shielding an injured player for 30 % of their missing health.\n\nYou already have this curio in your collection." }
entries[456960] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nUnbreakable Iron Idol\nWhen any player's health falls below 40 % health during combat, the idol awakens dealing moderate Physical damage to nearby enemies and taunting them for 6 sec. Can only occur every 2 min.\n\nYou already have this curio in your collection." }
entries[456961] = { ["name"] = "Become Well Fed", ["text"] = "Instant\nIncreases stats and grants additional effects depending on the type of Khaz Algar Food consumed." }
entries[456962] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nLight-Touched Idol\nWhen any player uses a defensive ability with a cooldown of 30 sec or longer, the idol activates and heals them for ( 200 / 100)% of their maximum health every 1 sec for 10 sec.\n\nYou already have this curio in your collection." }
entries[456963] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nIdol of Final Will\nDuring combat, Brann designates a player to guide his shot for 4 sec before firing towards their location and dealing significant Physical damage to the first enemy hit.\n\nYou already have this curio in your collection." }
entries[456965] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nAmorphous Relic\nUpon entering combat, players gain either Massive or Miniature until combat ends.\n\nMassive\nIncreases your size by 20%, maximum health by 10%, and damage and healing done by 6%.\n\nMiniature\nReduces your size by 20%, increases movement speed by 10%, and your haste by 6%.\n\nYou already have this curio in your collection." }
entries[456966] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nTime Lost Relic\nBrann's spell and abilities have a chance to create bursts of energy, warping the flow of time for all nearby units by 20 % for 12 sec.\n\nCasting, movement, periodic effects, cooldowns, and attack speeds are affected while time warped.\n\nYou already have this curio in your collection." }
entries[456967] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nOlden Seeker Relic\nWhen Brann uses Gathering Tools , there is a 35 % chance to unearth a powerful artifacts that grants your party a powerful Boon.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.\n\nYou already have this curio in your collection." }
entries[456968] = { ["name"] = "Refreshment", ["text"] = "Instant\nRestores ( 1350000 / 5 * 20) health and ( 675000 / 5 * 20) mana over 20 sec. Must remain seated while eating.\n\nWell Fed\nIf you spend at least 10 seconds eating you will become Well Fed and gain ( 470 * .7) Critical Strike for 1 hour." }
