entries[457052] = { ["name"] = "Deathstalker's Mark", ["text"] = "Assassination\nAmbush from Stealth applies 3 stacks of Deathstalker's Mark to your target. When you spend 5 or more combo points on attacks against a Marked target you consume an application of Deathstalker's Mark, dealing (120% of Attack Power) Plague damage and increasing the damage of your next Ambush or Mutilate by 50%.\nYou may only have one target Marked at a time.\n\nSubtlety\nShadowstrike from Stealth or Shadow Dance applies 3 stacks of Deathstalker's Mark to your target. When you spend 5 or more combo points on attacks against a Marked target you consume an application of Deathstalker's Mark, dealing (120% of Attack Power) Plague damage and increasing the damage of your next by 50%.\nYou may only have one target Marked at a time." }
entries[457053] = { ["name"] = "Clear the Witnesses", ["text"] = "Assassination\nYour next Fan of Knives after applying Deathstalker's Mark deals an additional (100% of Attack Power) Plague damage and generates 1 additional combo point.\n\nSubtlety\nYour next Shuriken Storm after applying Deathstalker's Mark deals an additional (100% of Attack Power) Plague damage and generates 1 additional combo point." }
